import sys
import math

def is_prime(n):
    if n < 2:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    for i in range(3, int(math.sqrt(n)) + 1, 2):
        if n % i == 0:
            return False
    return True

def main():
    line = sys.stdin.readline().strip()
    if not line:
        print(0)
        return

    digits = [int(d) for d in line]
    n = len(digits)

    result = 0
    for i in range(n):
        pos = i + 1
        if is_prime(pos):
            result += digits[i]

    print(result)

if __name__ == "__main__":
    main()
